USE pateek;

CREATE TABLE IF NOT EXISTS event_rsvps (
    RSVP_ID INT UNSIGNED NOT NULL AUTO_INCREMENT,
    EventID INT NOT NULL,
    Guest_Name VARCHAR(120) NOT NULL,
    Guest_Email VARCHAR(180) NOT NULL,
    Guest_Phone VARCHAR(30) NULL,
    RSVP_Token CHAR(64) NOT NULL,
    RSVP_Status ENUM('Pending','Confirmed','Declined','Waitlisted') NOT NULL DEFAULT 'Pending',
    Checked_In_At DATETIME NULL,
    Created_At TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (RSVP_ID), UNIQUE KEY uq_rsvp_token (RSVP_Token), KEY idx_rsvp_event (EventID),
    CONSTRAINT fk_rsvp_event FOREIGN KEY (EventID) REFERENCES Event(EventID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS event_tasks (
    Task_ID INT UNSIGNED NOT NULL AUTO_INCREMENT, EventID INT NOT NULL, Title VARCHAR(180) NOT NULL, Details TEXT NULL, Assigned_To VARCHAR(100) NULL, Due_Date DATE NULL, Priority ENUM('Low','Normal','High','Urgent') NOT NULL DEFAULT 'Normal', Task_Status ENUM('Todo','In Progress','Done','Blocked') NOT NULL DEFAULT 'Todo', Created_By VARCHAR(100) NOT NULL, Created_At TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (Task_ID), KEY idx_task_event (EventID), CONSTRAINT fk_task_event FOREIGN KEY (EventID) REFERENCES Event(EventID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS event_vendors (
    Vendor_ID INT UNSIGNED NOT NULL AUTO_INCREMENT, EventID INT NOT NULL, Vendor_Name VARCHAR(160) NOT NULL, Service_Type VARCHAR(100) NOT NULL, Contact_Name VARCHAR(120) NULL, Contact_Email VARCHAR(180) NULL, Contact_Phone VARCHAR(30) NULL, Contract_Status ENUM('Requested','Quoted','Confirmed','Completed','Cancelled') NOT NULL DEFAULT 'Requested', Notes TEXT NULL, Created_At TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (Vendor_ID), KEY idx_vendor_event (EventID), CONSTRAINT fk_vendor_event FOREIGN KEY (EventID) REFERENCES Event(EventID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS event_expenses (
    Expense_ID INT UNSIGNED NOT NULL AUTO_INCREMENT, EventID INT NOT NULL, Vendor_ID INT UNSIGNED NULL, Description VARCHAR(180) NOT NULL, Estimated_Amount DECIMAL(15,2) NOT NULL DEFAULT 0, Actual_Amount DECIMAL(15,2) NULL, Payment_Status ENUM('Unpaid','Partially Paid','Paid') NOT NULL DEFAULT 'Unpaid', Due_Date DATE NULL, Receipt_Path VARCHAR(255) NULL, Created_At TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (Expense_ID), KEY idx_expense_event (EventID), CONSTRAINT fk_expense_event FOREIGN KEY (EventID) REFERENCES Event(EventID) ON DELETE CASCADE, CONSTRAINT fk_expense_vendor FOREIGN KEY (Vendor_ID) REFERENCES event_vendors(Vendor_ID) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS event_seating_tables (Table_ID INT UNSIGNED NOT NULL AUTO_INCREMENT, EventID INT NOT NULL, Table_Name VARCHAR(80) NOT NULL, Capacity INT UNSIGNED NOT NULL DEFAULT 1, PRIMARY KEY (Table_ID), KEY idx_seating_event (EventID), CONSTRAINT fk_seating_event FOREIGN KEY (EventID) REFERENCES Event(EventID) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS event_seating_assignments (Assignment_ID INT UNSIGNED NOT NULL AUTO_INCREMENT, Table_ID INT UNSIGNED NOT NULL, RSVP_ID INT UNSIGNED NOT NULL, Seat_Number INT UNSIGNED NULL, PRIMARY KEY (Assignment_ID), UNIQUE KEY uq_seating_rsvp (RSVP_ID), CONSTRAINT fk_assignment_table FOREIGN KEY (Table_ID) REFERENCES event_seating_tables(Table_ID) ON DELETE CASCADE, CONSTRAINT fk_assignment_rsvp FOREIGN KEY (RSVP_ID) REFERENCES event_rsvps(RSVP_ID) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS event_templates (Template_ID INT UNSIGNED NOT NULL AUTO_INCREMENT, Template_Name VARCHAR(140) NOT NULL, Description TEXT NULL, Default_Status VARCHAR(30) NULL, Default_Budget DECIMAL(15,2) NULL, Created_By VARCHAR(100) NOT NULL, Created_At TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (Template_ID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS event_public_pages (Public_Page_ID INT UNSIGNED NOT NULL AUTO_INCREMENT, EventID INT NOT NULL, Public_Token CHAR(64) NOT NULL, Description TEXT NULL, Is_Published TINYINT(1) NOT NULL DEFAULT 0, Created_At TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (Public_Page_ID), UNIQUE KEY uq_public_event (EventID), UNIQUE KEY uq_public_token (Public_Token), CONSTRAINT fk_public_event FOREIGN KEY (EventID) REFERENCES Event(EventID) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS event_reviews (Review_ID INT UNSIGNED NOT NULL AUTO_INCREMENT, EventID INT NOT NULL, Guest_Email VARCHAR(180) NULL, Rating TINYINT UNSIGNED NOT NULL, Comments TEXT NULL, Created_At TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (Review_ID), KEY idx_review_event (EventID), CONSTRAINT fk_review_event FOREIGN KEY (EventID) REFERENCES Event(EventID) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS event_notifications (Notification_ID INT UNSIGNED NOT NULL AUTO_INCREMENT, Username VARCHAR(100) NOT NULL, EventID INT NULL, Notification_Type VARCHAR(50) NOT NULL, Message VARCHAR(255) NOT NULL, Is_Read TINYINT(1) NOT NULL DEFAULT 0, Created_At TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (Notification_ID), KEY idx_notification_user (Username), CONSTRAINT fk_notification_event FOREIGN KEY (EventID) REFERENCES Event(EventID) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS event_audit_log (Audit_ID BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, Username VARCHAR(100) NOT NULL, Action_Name VARCHAR(80) NOT NULL, Entity_Name VARCHAR(80) NOT NULL, Entity_ID VARCHAR(80) NULL, Details TEXT NULL, Created_At TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (Audit_ID), KEY idx_audit_created (Created_At), KEY idx_audit_entity (Entity_Name, Entity_ID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS event_tickets (
    Ticket_ID INT UNSIGNED NOT NULL AUTO_INCREMENT,
    EventID INT NOT NULL,
    Ticket_Name VARCHAR(100) NOT NULL,
    Price DECIMAL(10,2) NOT NULL DEFAULT 0,
    Capacity INT UNSIGNED NULL,
    Created_At TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (Ticket_ID),
    KEY idx_ticket_event (EventID),
    CONSTRAINT fk_ticket_event FOREIGN KEY (EventID) REFERENCES Event(EventID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS event_reminders (
    Reminder_ID INT UNSIGNED NOT NULL AUTO_INCREMENT,
    Username VARCHAR(100) NOT NULL,
    EventID INT NOT NULL,
    Remind_At DATETIME NOT NULL,
    Is_Sent TINYINT(1) NOT NULL DEFAULT 0,
    Created_At TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (Reminder_ID),
    UNIQUE KEY uq_user_event_reminder (Username, EventID),
    CONSTRAINT fk_reminder_event FOREIGN KEY (EventID) REFERENCES Event(EventID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ALTER TABLE event_rsvps ADD COLUMN IF NOT EXISTS Ticket_ID INT UNSIGNED NULL;
ALTER TABLE event_rsvps ADD KEY IF NOT EXISTS idx_rsvp_ticket (Ticket_ID);
ALTER TABLE event_rsvps ADD CONSTRAINT fk_rsvp_ticket FOREIGN KEY (Ticket_ID) REFERENCES event_tickets(Ticket_ID) ON DELETE SET NULL;
